/* Site settings. This file is NOT regenerated by update_site.sh. */
(function () {
  // When the site is served by "_build/backend/ee_faq_server.py" (on this Mac or
  // on the department network) the API lives at /api and editor sign-in works.
  // On a plain web host there is no /api, so the hosted backend is used instead.
  var h = location.hostname;
  var servedLocally =
    location.protocol !== "file:" &&
    (h === "localhost" || h === "127.0.0.1" || /\.local$/i.test(h) ||
     /^10\./.test(h) || /^192\.168\./.test(h) || /^172\.(1[6-9]|2\d|3[01])\./.test(h));

  // Paste the Google Apps Script web app URL here after setup (ends in /exec).
  // Leave empty to run without tracking; "Ask a question" then opens a pre-filled email instead.
  var hostedEndpoint = "";

  window.FAQ_CONFIG = {
    endpoint: servedLocally ? "/api" : hostedEndpoint,

    coordinatorEmail: "Belinda.Guevara@utsa.edu",

    // Shown in "Most asked questions" until enough real visits have been counted.
    defaultMostAsked: [
      "1-i-was-just-admitted-what-should-i-do-first",
      "4-am-i-eligible-for-the-qualifying-exam-qe1-and-how-do-i-sig",
      "3-what-paperwork-do-i-need-to-graduate-with-an-ms",
      "6-how-do-i-request-a-reduced-course-load-rcl-in-my-final-sem",
      "7-i-was-assigned-as-a-gta-what-are-the-requirements",
      "5-how-and-when-do-i-apply-for-graduation"
    ],
    // Minimum counted views before live rankings replace the defaults.
    minViewsForLiveRanking: 25
  };
})();
